const FeatureTour = defineAsyncComponent(() => import('../components/FeatureTour.vue'));
const touring = ref(false); const tourButton = ref<HTMLButtonElement>();
async function closeTour() { touring.value = false; await nextTick(); tourButton.value?.focus(); }
async function startTour() { navigate('overview'); await nextTick(); touring.value = true; }
import { useDashboard } from '../composables/useDashboard';
