useAdminReportAlerts(user, notices, demo, inboxReady);
const readingOpen = ref(false);
const filterLabels = computed(() => user.value?.role === 'admin' || view.value === 'mine' ? labels : Object.fromEntries(Object.entries(labels).filter(([status]) => acceptedStatuses.includes(status as keyof typeof labels))));
const mainContent = ref<HTMLElement | null>(null);
usePageMotion(mainContent, view);
const background = computed(() => municipalSettings.value.dashboard_background ? API_SERVER_URL + municipalSettings.value.dashboard_background : '');
const headerProps = computed(() => ({ section: view.value === 'guide' ? 'Settings / Guide' : navigation.value.find(item => item.id === view.value)?.label, time: philippineTime.value, online: online.value, demo: demo.value, admin: user.value?.role === 'admin', unread: unread.value, initial: user.value?.name.charAt(0).toUpperCase() || 'G' }));
const headerActions = { settings: () => navigate('settings'), notifications: openNotifications, account: () => { if (user.value) navigate('profile'); else modal.value = 'auth'; } };
const compactQuery = window.matchMedia('(max-width: 1023px)');
const compact = ref(compactQuery.matches);
let drawerOverflow = '';
function updateCompact() { compact.value = compactQuery.matches; if (!compact.value) mobileNav.value = false; }
onMounted(() => compactQuery.addEventListener('change', updateCompact));
onBeforeUnmount(() => { compactQuery.removeEventListener('change', updateCompact); if (mobileNav.value) document.body.style.overflow = drawerOverflow; });
watch(mobileNav, async open => {
  if (open) { drawerOverflow = document.body.style.overflow; document.body.style.overflow = 'hidden'; }
  else document.body.style.overflow = drawerOverflow;
  await nextTick();
  if (open) document.querySelector<HTMLButtonElement>('.sidebar nav button')?.focus();
  else if (compact.value && !modal.value && !selected.value && !readingOpen.value) document.querySelector<HTMLButtonElement>('.nav-more')?.focus();
});
watch(modal, value => { if (value) mobileNav.value = false; });
