on</h2><p>Recent active reports</p></div><span class="orange-dot"></span></div><div v-if="!urgent.length" class="small-empty"><ShieldCheck :size="29" /><strong>{{ loading ? 'Loading reports…' : 'No active reports to show' }}</strong><p>New reports will appear here.</p></div><button v-for="report in urgent" :key="report.id" class="attention-report" @click="selected = report"><div class="attention-top"><span class="category-icon" :class="report.category.id"><HazardIcon :category="report.category.id" :size="19" /></span><span class="severity" :class="report.severity">{{ report.severity }}</span></div><h3>{{ report.title }}</h3><p><MapPin :size="13" />{{ report.barangay }}</p><div class="attention-foot"><span class="status" :class="report.status">{{ labels[report.status] }}</span><small>{{ relativeTime(report.created_at) }}</small></div></button><button class="view-all" @click="navigate(user?.role === 'admin' ? 'reports' : 'map')">{{ user?.role === 'admin' ? 'View all reports' : 'View hazard map' }}<ArrowRight :size="16" /></button></aside></section>
        <section v-if="view !== 'map'" class="reports-panel" :aria-busy="loading"><div class="panel-heading"><div><h2>{{ view === 'mine' ? 'Your submitted reports' : user?.role === 'admin' ? 'Recent reports' : 'Verified hazards' }} <span class="pill">{{ total }}</span></h2><p>{{ view === 'mine' ? 'All your submissions, including pending, accepted and rejected reports. Select one to view its history.' : 'Every report is a step toward a safer community' }}</p></div><button class="button secondary small" :disabled="!filtered.length" @click="exportCsv"><Download :size="15" />Export page</button></div><div v-if="!filtered.length" class="empty-state"><ClipboardList :size="34" /><h3>{{ loading ? 'Loading reports…' : 'No reports found' }}</h3><p>{{ search || category || status ? 'Try another search or clear your filters.' : 'Reports will appear here when submitted to your municipality.' }}</p><button v-if="!loading && !online && !demo" class="button secondary" @click="toggleDemo(true)">Explore the demo workspace</button></div><template v-else><ReportCards :reports="filtered.slice(0, view === 'overview' ? 5 : 100)" @select="selected = $event" /><div class="table-scroll"><table><thead><tr><th>HAZARD DETAILS</th><th>LOCATION</th><th>PRIORITY</th><th>STATUS</th><th>REPORTED</th><th><span class="visually-hidden">Open report</span></th></tr></thead><tbody><tr v-for="report in filtered.slice(0, view === 'overview' ? 5 : 100)" :key="report.id"><td><button class="table-report" @click="selected = report"><span class="category-icon" :class="report.category.id"><HazardIcon :category="report.category.id" /></span><span><strong>{{ report.title }}</strong><small>{{ report.reference_number }} <span>·</span> {{ report.category.name }}</small></span></button></td><td><div class="table-location"><MapPin :size="14" />{{ report.barangay }}</div></td><td><span class="severity" :class="report.severity">{{ report.severity }}</span></td><td><span class="status" :class="report.status">{{ labels[report.status] }}</span></td><td class="muted nowrap">{{ relativeTime(report.created_at) }}</td><td><button class="icon-button" :aria-label="`Open ${report.reference_number}`" @click="selected = report"><ChevronRight :size="17" /></button></td></tr></tbody></table></div></template><footer class="table-footer"><span>Showing {{ Math.min(filtered.length, view === 'overview' ? 5 : 100) }} reports{{ demo ? ' · Demo data' : '' }}</span><button v-if="view === 'overview'" class="text-button" @click="navigate(user?.role === 'admin' ? 'reports' : 'map')">{{ user?.role === 'admin' ? 'View all reports' : 'View hazard map' }} <ArrowRight :size="15" /></button><div v-else class="pagination"><button class="icon-button" :disabled="page <= 1" aria-label="Previous page" @click="page--; refresh()"><ChevronLeft :size="17" /></button><span>{{ page }} / {{ lastPage }}</span><button class="icon-button" :disabled="page >= lastPage" aria-label="Next page" @click="page++; refresh()"><ChevronRight :size="17" /></button></div></footer></section>
      </template>

