      <footer class="page-footer"><span><ShieldCheck :size="14" />Built for a safer, more connected community.</span><span>{{ demo ? 'Preview · No live incidents' : synced ? `Last synced ${synced}` : identity.name + ' - ' + identity.subtitle }}</span></footer>
    </main></div>
